export class Soundscape{
 constructor(){this.muted=false;this.ctx=null;this.song=new Audio('assets/audio/i-was-away.mp3');this.song.loop=true;this.song.volume=.19;this.flight=null}
 async start(){if(!this.ctx){this.ctx=new (window.AudioContext||window.webkitAudioContext)();this.master=this.ctx.createGain();this.master.gain.value=.5;this.master.connect(this.ctx.destination);const len=this.ctx.sampleRate*8;this.noise=this.ctx.createBuffer(1,len,this.ctx.sampleRate);let b=0;const d=this.noise.getChannelData(0);for(let i=0;i<len;i++){b=(b+Math.random()*.025-.0125)/1.012;d[i]=b*4;}const src=this.ctx.createBufferSource();src.buffer=this.noise;src.loop=true;const low=this.ctx.createBiquadFilter();low.type='lowpass';low.frequency.value=550;const gain=this.ctx.createGain();gain.gain.value=.07;src.connect(low).connect(gain).connect(this.master);src.start();this.ambience=src;}await this.ctx.resume();if(!this.muted)this.song.play().catch(()=>{});}
 toggle(){this.muted=!this.muted;if(this.master)this.master.gain.setTargetAtTime(this.muted?0:.5,this.ctx.currentTime,.2);this.song.muted=this.muted;return this.muted}
 suspend(){this.song.pause();this.ctx?.suspend()}
 resume(){if(this.ctx){this.ctx.resume();if(!this.muted)this.song.play().catch(()=>{})}}
 whoosh(strength=1){if(!this.ctx||this.muted)return;const t=this.ctx.currentTime;const src=this.ctx.createBufferSource();src.buffer=this.noise;const f=this.ctx.createBiquadFilter();f.type='bandpass';f.frequency.setValueAtTime(1100,t);f.frequency.exponentialRampToValueAtTime(180,t+.7);const g=this.ctx.createGain();g.gain.setValueAtTime(.001,t);g.gain.exponentialRampToValueAtTime(.7*strength,t+.07);g.gain.exponentialRampToValueAtTime(.001,t+.85);src.connect(f).connect(g).connect(this.master);src.start();src.stop(t+.9)}
 tick(perfect=false){if(!this.ctx||this.muted)return;const t=this.ctx.currentTime;const osc=this.ctx.createOscillator();const g=this.ctx.createGain();osc.type='sine';osc.frequency.setValueAtTime(perfect?660:440,t);osc.frequency.exponentialRampToValueAtTime(perfect?330:190,t+.2);g.gain.setValueAtTime(.001,t);g.gain.exponentialRampToValueAtTime(.12,t+.009);g.gain.exponentialRampToValueAtTime(.001,t+.36);osc.connect(g).connect(this.master);osc.start(t);osc.stop(t+.4);this.whoosh(.2)}
 shutter(phase='release',index=0){if(!this.ctx||this.muted)return;const t=this.ctx.currentTime;for(const [delay,level] of [[0,.19],[.065,.08]]){const buffer=this.ctx.createBuffer(1,Math.ceil(this.ctx.sampleRate*.055),this.ctx.sampleRate);const data=buffer.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=(Math.random()*2-1)*Math.exp(-i/(data.length*.14));const src=this.ctx.createBufferSource();src.buffer=buffer;const f=this.ctx.createBiquadFilter();f.type='highpass';f.frequency.value=phase==='apex'?1300:950;const g=this.ctx.createGain();g.gain.value=level*(1+index*.06);src.connect(f).connect(g).connect(this.master);src.start(t+delay);}}
 update(progress){if(!this.ctx||this.muted)return;if(progress>.76&&progress<.78&&!this.returnSound){this.returnSound=true;this.whoosh(.6)}if(progress<.1)this.returnSound=false;}
}
